// === Tab: mySketch ===
function setup() {
	createCanvas(1112,834);
	background(0);
	colorMode(HSB);
	frameCount=90
}

var bounce = false
var firepower = 20;
var g = 20
var particles=[];
var ar=0;
var sp=false

function draw() {
	background(0,.1)
	if(frameCount%50==0){
	  fireWork(random(width),random(height),random(50,100))
	}if(frameCount%100==0){
	   fireWork(random(width),random(height),random(50,150))
	}if(frameCount%10==0){
	   fireWork(random(width),random(height),random(50,60))
	}
	ar=0
	for(let i=0;i<particles.length;i++){
    sp=false
		particles[i].update();
		if(particles[i].x>width||particles[i].x<0){if(bounce){particles[i].xv*=-0.5}else{sp=true}}
		if(particles[i].y<0){if(bounce){particles[i].yv*=-0.3}else{sp=true}}
						if(particles[i].y>height){sp=true}
		ar++;
		if(sp){particles.splice(i,1);
					i--;
					}
	}
  fill(255);
	stroke(0);
	strokeWeight(4);
	textAlign(CENTER)
	textSize(100)	
	text("Happy New Year!",width/2,200)
	fill(45, 200, 255);
	textSize(80)
	text("First day of 2022!",width/2,350)
	noStroke();
}

function mousePressed(){fireWork((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),random(50,100))}

function fireWork(x,y,s){
	for(let i=0;i<s;i++){
  particles.push(new Particle(x,y))}
}

function Particle(x,y){
	this.x=x;
	this.y=y;
	this.xv=random(firepower-random(firepower),-firepower+random(firepower));
	this.yv=random(firepower-random(firepower),-firepower+random(firepower));
	this.g=2;
	this.fill=random(255)
	this.fill2=255
	this.fill3=255
	this.fill4=1
	this.update=function(){
		this.x+=this.xv
		this.y+=this.yv
		this.y+=this.g
		this.g+=this.g/(50-g)

fill(this.fill,this.fill2,this.fill3,this.fill4)
		noStroke();
		ellipse(this.x,this.y,5)
	}
} 

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

